public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (distances[u] != Integer.MAX_VALUE) {
                distances[v] = Math.min(distances[v], distances[u] + 1);
            }
        }
    }

    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time += distances[i];
        }
    }

    return time;
}

