public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    int sumLeft = 0;
    int countLeft = 0;
    for (int num : nums) {
        if (sumLeft + num <= sum) {
            sumLeft += num;
            countLeft++;
        }
        if (sumLeft == average * countLeft) {
            return true;
        }
    }
    return false;
}

