public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = 0, dp1 = 0;
    for (int i = 0; i < n; i++) {
        int temp = dp0;
        dp0 = Math.min(dp0, dp1) + cost[i];
        dp1 = temp;
    }
    return Math.min(dp0, dp1);
}

