public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    int maxElement = arr[n - 1];
    for (int i = n - 1; i >= 0; i--) {
        if (arr[i] != maxElement) {
            minOperations++;
            int x = i;
            int y = n - 1;
            arr[x] -= 1;
            arr[y] += 1;
            maxElement = arr[n - 1];
        }
    }
    return minOperations;
}

