        // Iterate through the paths parameter to check if any path is invalid.
        // A path is invalid if it connects two n-tersections that are not adjacent.
        for (int[] path : paths) {
            // Check if the starting and ending n-tersection coordinates are valid.
            if (path.length != 2 || path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
                // The current path is invalid. Set canTravel to false and break the loop.
                canTravel = false;
                break;
            }
        }

        // Check if travel is possible. If canTravel is true, return "can be travelled".
        // If canTravel is false, return "cannot be travelled".
        return canTravel ? "can be travelled" : "cannot be travelled";
    }

