public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;
    int[] dist = new int[n];
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    queue.add(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        visited[node] = true;
        for (int neighbor : edges[node]) {
            if (!visited[neighbor]) {
                queue.add(neighbor);
                dist[neighbor] = Math.min(dist[neighbor], dist[node] + (hasApple[neighbor] ? 2 : 1));
            }
        }
    }
    return dist[0];
}

