public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;
    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(0);
    visited[0] = true;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        time += hasApple[node] ? 2 : 1;

        for (int neighbor : findNeighbors(edges, node)) {
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    return time;
}

