public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    int avg = sum / n;
    int leftSum = 0;
    for (int i = 0; i < n / 2; i++) {
        leftSum += nums[i];
    }
    if (leftSum == avg) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    int rightSum = sum - leftSum;
    return rightSum == avg;
}

