public static String addThousandSeparator(int n) {
    String str = String.valueOf(n);
    if (str.length() <= 3) {
        return str;
    }
    int numSeparators = (str.length() - 1) / 3;
    StringBuilder sb = new StringBuilder();
    sb.append(str.substring(0, str.length() - (3 * numSeparators)));
    for (int i = 0; i < numSeparators; i++) {
        sb.append(".");
        sb.append(str.substring(str.length() - (3 * (i + 1)), str.length() - (3 * i)));
    }
    return sb.toString();
