public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLen = 1;
                // horizontal
                for (int k = j + 1; k < n && mat[i][k] == 1; k++) {
                    currentLen++;
                }
                // vertical
                for (int k = i + 1; k < m && mat[k][j] == 1; k++) {
                    currentLen++;
                }
                // diagonal
                for (int k = 1; i + k < m && j + k < n && mat[i + k][j + k] == 1; k++) {
                    currentLen++;
                }
                // anti-diagonal
                for (int k = 1; i + k < m && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
                    currentLen++;
                }
                maxLen = Math.max(maxLen, currentLen);
            }
        }
    }

    return maxLen;
}

