public static int calculateEnergy(String s) {
    int energy = 1;
    char currentChar = s.charAt(0);
    int currentCharIndex = 0;

    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentCharIndex = i;
        } else {
            energy = Math.max(energy, i - currentCharIndex);
            currentChar = c;
            currentCharIndex = i;
        }
    }

    energy = Math.max(energy, s.length() - currentCharIndex);
    return energy;
}

