public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int num = i;
        boolean greaterTen = false;
        while (num % 10 == 0) {
            num /= 10;
            greaterTen = true;
        }
        if (greaterTen) {
            result.add(i);
        } else {
            int digit = num % 10;
            int index = digit - 1;
            while (result.size() > index && result.get(index) > digit) {
                index++;
            }
            result.add(index, digit);
        }
    }
    return result;
}

