public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int operations = 0;
    while (true) {
        int max = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }

        boolean allEqual = true;
        for (int i = 0; i < n; i++) {
            if (arr[i] != max) {
                allEqual = false;
            }
        }

        if (allEqual) {
            break;
        }

        int x = 0;
        int y = 0;
        for (int i = 1; i < n; i++) {
            if (arr[i] < arr[i - 1]) {
                x = i - 1;
                y = i;
                break;
            }
        }

        arr[x] -= 1;
        arr[y] += 1;
        operations++;
    }

    return operations;
}

