    int n = mat[0].length;
    int maxLen = 0;

    // horizontal search
    for (int i = 0; i < m; i++) {
        int len = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) len++;
            else len = 0;
            maxLen = Math.max(maxLen, len);
        }
    }

    // vertical search
    for (int j = 0; j < n; j++) {
        int len = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) len++;
            else len = 0;
            maxLen = Math.max(maxLen, len);
        }
    }

    // diagonal search
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int len = 0;
            int ii = i, jj = j;
            while (ii < m && jj < n && mat[ii][jj] == 1) {
                len++;
                ii++;
                jj++;
            }
            maxLen = Math.max(maxLen, len);
        }
    }

    // anti-diagonal search
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            int len = 0;
            int ii = i, jj = j;
            while (ii < m && jj >= 0 && mat[ii][jj] == 1) {
                len++;
                ii++;
                jj--;
            }
            maxLen = Math.max(maxLen, len);
        }
    }

    return maxLen;
}

