public int minInsertions(String s) {
    int leftCount = 0;
    int rightCount = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftCount++;
        } else {
            rightCount++;
        }
    }
    int minInsertions = Math.abs(leftCount - rightCount);
    if (leftCount > rightCount) {
        minInsertions += leftCount - rightCount;
    }
    return minInsertions;
