public int search(int[] nums, int target) {
    int low = 0, high = nums.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        int midVal = nums[mid];

        if (midVal == target) {
            return mid;
        }

        if (midVal >= nums[low]) {
            if (target >= nums[low] && target < midVal) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        } else {
            if (target > midVal && target <= nums[high]) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
    }
    return -1;
}

