public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parent = new int[n];
    int[] distance = new int[n];
    boolean[] visited = new boolean[n];

    for (int i = 0; i < n; i++) {
        parent[i] = -1;
        distance[i] = 0;
        visited[i] = false;
    }

    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        parent[v] = u;
    }

    PriorityQueue<Integer> queue = new PriorityQueue<>();
    visited[0] = true;
    queue.add(0);

    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : edges[u]) {
            if (!visited[v]) {
                visited[v] = true;
                queue.add(v);
                distance[v] = distance[u] + 1;
                parent[v] = u;
            }
        }
    }

    int total = 0;
    for (int i = 1; i < n; i++) {
        if (hasApple[i]) {
            total += distance[i];
        }
    }

    return total;
}

