        parent[v] = u;
    }

    PriorityQueue<Integer> queue = new PriorityQueue<>();
    visited[0] = true;
    queue.add(0);

    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : edges[u]) {
            if (!visited[v]) {
                visited[v] = true;
                queue.add(v);
                distance[v] = distance[u] + 1;
                parent[v] = u;
            }
        }
    }

    int total = 0;
    for (int i = 1; i < n; i++) {
        if (hasApple[i]) {
            total += distance[i];
        }
    }

    return total;
}

