    generated_numbers = set()

    # Add the original number to the set
    generated_numbers.add(n)

    # Loop through each rule and apply the transformation
    for rule in rules:
        # Get the digit to transform and the replacement digit
        digit_to_transform, replacement_digit = rule

        # Loop through the digits of the original number
        for i in range(len(str(n))):
            # If the digit matches the digit to transform, replace it with the replacement digit
            if str(n)[i] == str(digit_to_transform):
                # Get the new number by replacing the digit at position i with the replacement digit
                new_number = int(str(n)[:i] + str(replacement_digit) + str(n)[i+1:])

                # Add the new number to the set if it is not already present
                if new_number not in generated_numbers:
                    generated_numbers.add(new_number)

    # Return the count of unique numbers generated
    return len(generated_numbers)

