def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ""
        if coeff < 0:
            term += "-"
        else:
            term += "+"
        # Don't include '+x' for the first term
        if i > 0 or coeff != 1:
            abs_coeff = abs(coeff)
            term += str(abs_coeff)
            if abs_coeff != 1 or i > 1:
