public double trimMean(int[] arr) {
    // Calculate the number of elements to remove
    int numToRemove = arr.length * 0.05;
    // Create a new array with the elements removed
    int[] newArr = new int[arr.length - 2 * numToRemove];

    // Sort the array descending
    Arrays.sort(arr, Collections.reverseOrder());

    // Remove the smallest and largest elements
    for (int i = 0; i < numToRemove; i++) {
        newArr[i] = arr[i + numToRemove];
    }
    for (int i = numToRemove; i < arr.length - numToRemove; i++) {
        newArr[i - numToRemove] = arr[i];
    }

    // Calculate the mean
    double sum = 0;
    for (int i = 0; i < newArr.length; i++) {
        sum += newArr[i];
    }
    return sum / newArr.length;
}

