def min_time(n, edges, has_apple):
    # Initialize the graph with the given edges
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize the visit array
    visit = [False] * n

    # Initialize the minimum time required
    min_time = 0

    # Perform a DFS traversal from node 0
    stack = [0]
    while stack:
        node = stack.pop()
        if not visit[node]:
            visit[node] = True
            for neighbor in graph[node]:
                if not visit[neighbor]:
                    if has_apple[neighbor]:
                        min_time += 2
                    stack.append(neighbor)

    return min_time

