public static int findSmallestInteger(int n) {
  // Split the digits of n into an array
  int[] digits = String.valueOf(n).chars().map(Character::getNumericValue).toArray();

  // Sort the digits in ascending order
  Arrays.sort(digits);

  // Build the smallest integer greater than n by concatenating the sorted digits
  StringBuilder sb = new StringBuilder();
  for (int i = digits.length - 1; i >= 0; i--) {
    sb.append(digits[i]);
  }

  // Check if the resulting integer is greater than n
  int result = Integer.parseInt(sb.toString());
  if (result > n) {
    return result;
  } else {
    return -1;
  }
}

