public static boolean isBoomerang(int[][] points) {
if (points.length != 3) {
return false;
}

int[] p1 = points[0];
int[] p2 = points[1];
int[] p3 = points[2];

int slope1 = (p2[1] - p1[1]) / (p2[0] - p1[0]);
int slope2 = (p3[1] - p1[1]) / (p3[0] - p1[0]);

return slope1 != slope2 && (p1[0] - p2[0]) * (p3[1] - p2[1]) == (p1[1] - p2[1]) * (p3[0] - p2[0]);
}

