public static int findNthUglyNumber(int n) {
   int base = 1;
   int multiple = 6;
   Set<Integer> uglyNumbers = new HashSet<>();
   uglyNumbers.add(1);
   while (uglyNumbers.size() < n) {
       for (int i = base; i < multiple; i++) {
           if (uglyNumbers.contains(i)) {
               int next = i * base;
               if (next < multiple && !uglyNumbers.contains(next)) {
                   uglyNumbers.add(next);
               }
           }
       }
       base += 1;
       multiple *= 6;
   }
   return beautifulNumber;
}

