public static int calculateEnergy(String s) {
    int maxLength = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentChar = c;
            currentLength = 1;
        }
    }
    return Math.max(maxLength, currentLength);
}

