public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Initialize a graph with n nodes
        Graph graph = new Graph(n);

        // Add edges to the graph
        for (int[] edge : edges) {
            graph.addEdge(edge[0], edge[1]);
        }

        // Perform a breadth-first search from node 0
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        visited[0] = true;

        int minTime = 0;
        while (!queue.isEmpty()) {
            int curr = queue.poll();
            for (int node : graph.getNeighbors(curr)) {
                if (!visited[node]) {
                    if (hasApple[node]) {
                        minTime += 2;
                    }
                    visited[node] = true;
                    queue.add(node);
                }
            }
        }

        return minTime;
    }

