public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]][start[1]] = true;
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.remove();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            int[] path = paths[i];

            // If the path is not blocked and the destination n-tersection has not been visited, mark it as visited and add it to the queue
            if (path[0] != -1 && !visited[path[0]][path[1]]) {
                visited[path[0]][path[1]] = true;
                queue.add(new int[] {path[0], path[1]});
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited[end[0]][end[1]]) {
        return "cannot be travelled";
    }

    // Return "can be travelled" if the ending n-tersection has been visited
    return "can be travelled";
}

