        Stack<Character> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c >= 'A' && c <= 'Z') {
                // Uppercase letter
                if (!stack.isEmpty() && stack.peek() == 'a' + (c - 'A')) {
                    // There is a corresponding lowercase letter, so unwrap
                    stack.pop();
                } else {
                    // No corresponding lowercase letter, so add to result
                    result.append(c);
