public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    boolean[] seen = new boolean[1 << k];
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = (code << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
            code &= (1 << k) - 1;
        }
    }
    return !seen[0];
}

