public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[k + 1];
    fib[0] = 1;
    fib[1] = 1;
    for (int i = 2; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int count = 0;
    for (int i = k; i > 0; i--) {
        while (fib[i] > 0 && k > 0) {
            count++;
            fib[i]--;
            k--;
        }
    }
    return count;
}

