public boolean isValidBST(TreeNode root) {
    return isValidBST(root, null, null);
}

private boolean isValidBST(TreeNode node, Integer lower, Integer upper) {
    if (node == null) {
        return true;
    }
    int val = node.val;
    if (lower != null && val <= lower) {
        return false;
    }
    if (upper != null && val >= upper) {
        return false;
    }
    if (!isValidBST(node.left, lower, val)) {
        return false;
    }
    if (!isValidBST(node.right, val, upper)) {
        return false;
    }
    return true;
}

Note: The binary tree in the test cases is represented in a flattened form. Each non-leaf node is indicated by a pair of parentheses ( ) that enclose a list of keys separated by commas. The left child is represented by the first key in the list, and the right child is represented by the last key in the list.

