public String getSmallestString(int n, int k) {
    // We can start with the smallest lexicographically possible string, which is all 'a's
    String smallest = "a".repeat(n);
    int value = 1;
    for (int i = 1; i <= n && value < k; i++) {
        // We can try to add more 'a's to the end of the string to increase its value
        String candidate = smallest + "a";
        if (candidate.length() > n) {
            break;
        }
        value += 1;
        if (value == k) {
            return candidate;
        } else if (value > k) {
            break;
        }
        smallest = candidate;
    }
    return smallest;
}

