    // Initialize an array to store the Fibonacci numbers.
    int[] fib = new int[k + 1];
    fib[0] = 0;
    fib[1] = 1;

    // Initialize a variable to keep track of the number of Fibonacci numbers used.
    int count = 0;

    // Loop through the array and find the minimum number of Fibonacci numbers that sum up to k.
    for (int i = 2; i < fib.length; i++) {
        // If the current Fibonacci number is greater than or equal to k, we found the minimum number of Fibonacci numbers.
        if (fib[i] >= k) {
            break;
        }
        // If the current Fibonacci number is less than k, increment the count and add it to the sum.
        count++;
        k -= fib[i];
    }

    return count;
}

