public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> numbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        int prev = i % 10;
        boolean isStepping = true;
        while (i > 0) {
            int curr = i % 10;
            if (curr != prev + 1 && curr != prev - 1) {
                isStepping = false;
                break;
            }
            i /= 10;
            prev = curr;
        }
        if (isStepping) {
            numbers.add(i);
        }
    }
    Collections.sort(numbers);
    return numbers;
}

