    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) continue;

            int length = 1;
            while (i + 1 < m && mat[i + 1][j] == 1) {
                length++;
