public boolean canArrange(int[] arr, int k) {  
    if (arr.length % 2 != 0) { return false; }  
    if (k <= 0) { return false; }  

    int count = arr.length / 2;  
    int sum = 0;  
    int i = 0;  
    while (i < arr.length - 1 && count > 0) {  
        int pairSum = arr[i] + arr[i + 1];  
        if (pairSum % k == 0) {  
            count--;  
        }  
        sum += pairSum;  
        i += 2;  
    }  

    return sum % k == 0;  
}

