    // Check if the starting and ending points are valid
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Initialize a 2D array to store the visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Initialize a 2D array to store the paths between n-tersections
    boolean[][] validPaths = new boolean[n][n];

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Perform BFS to explore the n-teresting space
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        for (int i = 0; i < n; i++) {
            if (paths[current[0]][i] != 0 && !visited[i][current[1]]) {
                visited[i][current[1]] = true;
                queue.add(new int[]{i, current[1]});
            }
        }
    }

    // Check if the ending n-tersection is visited
    if (visited[end[0]][end[1]]) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

