public static String appx(String word1, String word2) {
    int commonLetters = 0;
    int length1 = word1.length();
    int length2 = word2.length();
    for (int i = 0; i < length1 && i < length2; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }
    int denominator = length1 + length2 - commonLetters;
    if (denominator == 0) {
        return "Invalid input: words are the same";
    }
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

