public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    List<Character> sorted = new ArrayList<>();
    while (sorted.size() < s.length()) {
        char smallest = '\uFFFF';
        char largest = '\0';
        for (char c : s.toCharArray()) {
            if (c < smallest) {
                smallest = c;
            }
            if (c > largest) {
                largest = c;
            }
        }
        sorted.add(smallest);
        sorted.add(largest);
        s = s.replaceFirst("" + smallest, "");
        s = s.replaceFirst("" + largest, "");
    }
    StringBuilder result = new StringBuilder();
    for (char c : sorted) {
        result.append(c);
    }
    return result.toString();
}

