public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    double trimAmount = (double) arr.length * 0.05;
    Arrays.sort(arr);
    int skip = (int) Math.floor(trimAmount);
    int trimmedLength = arr.length - 2 * skip;
    double sum = 0.0;
    for (int i = skip; i < trimmedLength; i++) {
        sum += arr[i];
    }
    return sum / trimmedLength;
}

