public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length == 0) {
        return false;
    }
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
    }
    double average = (double) sum / nums.length;
    int leftSum = 0;
    int rightSum = sum;
    for (int i = 0; i < nums.length - 1; i++) {
        leftSum += nums[i];
        rightSum -= nums[i];
        if (Math.abs((leftSum / (i + 1)) - (rightSum / (nums.length - i - 1))) <= 0.0001) {
            return true;
        }
    }
    return false;
}

