public boolean hasAllCodes(String s, int k) {
    // Check if the input string is valid
    if (s == null || s.length() == 0 || s.length() < k) {
        return false;
    }

    // Initialize a set to store all the binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // Loop through the input string and generate all binary strings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);
        binaryStrings.add(binaryString);
    }

    // Check if all binary strings of length k are substrings of the input string
    for (String binaryString : binaryStrings) {
        if (!s.contains(binaryString)) {
            return false;
        }
    }

    // If all binary strings of length k are substrings of the input string, return true
    return true;
}

