  for (int i = 0; i < sb.length() - 1; i++) {
    char curr = sb.charAt(i);
    char next = sb.charAt(i + 1);
    if (Character.isLowerCase(curr) && Character.isUpperCase(next) && curr == Character.toLowerCase(next)) {
      sb.deleteCharAt(i);
      sb.deleteCharAt(i + 1);
      i -= 2;
    }
  }
  return sb.toString();
}

