public String getSmallestString(int n, int k) {
    // Initialize the result string with the first character
    String result = "" + (char)('a' + k % 26);

    // Iterate over the remaining characters
    for (int i = 1; i < n; i++) {
        // Calculate the position of the current character in the alphabet
        int pos = (k - (i * 26)) % 26;

        // If the position is negative, add 26 to make it positive
        if (pos < 0) {
            pos += 26;
        }

        // Add the character to the result string
        result += (char)('a' + pos);
    }

    return result;
}

