public static double calculateProbability(int n) {
  if (n < 1) {
    throw new IllegalArgumentException("n must be a positive integer");
  }

  if (n == 1) {
    return 1.0;
  }

  long numberOfPassengers = n;
  long numberOfSeats = n;
  long numberOfLastSeatOccupied = 0;

  for (int i = 1; i <= n; i++) {
