public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                // Check horizontal
                int k = j + 1;
                while (k < mat[i].length && mat[i][k] == 1) {
                    currentLength++;
                    k++;
                }
                // Check vertical
                k = i + 1;
                while (k < mat.length && mat[k][j] == 1) {
                    currentLength++;
                    k++;
                }
                // Check diagonal
                k = j + 1;
                int idx = i + 1;
                while (k < mat[idx].length && mat[idx][k] == 1) {
                    currentLength++;
                    k++;
                    idx++;
                }
                // Check anti-diagonal
                k = j - 1;
                idx = i - 1;
                while (k >= 0 && idx >= 0 && mat[idx][k] == 1) {
                    currentLength++;
                    k--;
                    idx--;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

