        // Check that the angle between the first two points and the third point is not zero
        int[] vector1 = {points[1][0] - points[0][0], points[1][1] - points[0][1]};
        int[] vector2 = {points[2][0] - points[0][0], points[2][1] - points[0][1]};
        int dotProduct = vector1[0] * vector2[0] + vector1[1] * vector2[1];
        int magnitude1 = (int) Math.sqrt(vector1[0] * vector1[0] + vector1[1] * vector1[1]);
        int magnitude2 = (int) Math.sqrt(vector2[0] * vector2[0] + vector2[1] * vector2[1]);
        double angle = Math.abs(Math.acos(dotProduct / (magnitude1 * magnitude2)));
        if (angle < 0.000001) {
            return false;
        }

        return true;
    }

