public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int sum = i * i;
        if (sum > n) {
            break;
        }
        int remaining = n - sum;
        if (remaining == 0) {
            minSquares = 1;
        } else {
            int minRemainingSquares = minPerfectSquareSum(remaining);
            if (minRemainingSquares < minSquares) {
                minSquares = minRemainingSquares;
            }
        }
    }
    return minSquares;
}

