    checksum_digit = isbn[-1]
    if checksum_digit.isalpha() and checksum_digit.upper() == "X":
        checksum_digit = 10
    else:
        checksum_digit = int(checksum_digit)

    # Calculate the checksum digit using the ISBN standard calculation
    calculated_checksum = 0
    for i, digit in enumerate(isbn[:-1].replace("-", "")):
        if digit.isalpha():
            digit = ord(digit.upper()) - ord("A") + 10
        else:
