        if i % 2 == 0:
            calculated_checksum += digit
        else:
            calculated_checksum += digit * 3
    calculated_checksum = (10 - calculated_checksum % 10) % 10

    # Check if the calculated checksum matches the input checksum
    if calculated_checksum == checksum_digit:
        return "Right"
    else:
        return isbn[:-1] + str(calculated_checksum)

