public boolean canArrange(int[] arr, int k) {
  Set<Integer> set = new HashSet<>();
  for (int num : arr) {
    if (num % k == 0) {
      set.add(num / k);
    } else {
      set.add((num / k) + 1);
    }
  }

  return set.size() <= arr.length / 2;
}

