public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[] {1, 1, 1};
    int n = fib.length;
    while (fib[n - 1] < k) {
      fib[n] = fib[n - 1] + fib[n - 2];
      n++;
    }
    int count = 0;
    while (k > 0) {
      if (k >= fib[n - 1]) {
        k -= fib[n - 1];
        count++;
      } else {
        n--;
      }
    }
    return count;
  }

