    int next = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
    if (next == dp[i2] * 2) i2++;
    if (next == dp[i3] * 3) i3++;
    if (next == dp[i5] * 5) i5++;
    dp[i] = next;
  }
  return dp[n];
}

