public boolean splitArraySameAverage(int[] nums) {
    // Sort the array in ascending order
    Arrays.sort(nums);

    // Calculate the sum of the array elements
    int sum = Arrays.stream(nums).sum();

    // Calculate the average of the array
    double average = (double) sum / nums.length;

    // Check if the average is an integer
    if (average % 1 == 0) {
        // If the average is an integer, we need to check if there exists a value in the array
        // that is equal to the average
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == average) {
                return true;
            }
        }
    } else {
        // If the average is not an integer, we need to check if there exists a value in the array
        // that is equal to the average rounded up or down
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == (int) Math.floor(average)) {
                return true;
            }
            if (nums[i] == (int) Math.ceil(average)) {
                return true;
            }
        }
    }

    return false;
}

