public static int calculateTimeNeeded(int N) {
    // Iterative solution
    int time = 0;
    int[][] seat = new int[N][2];
    for (int i = 0; i < N; i++) {
        seat[i][0] = i; // original seat
        seat[i][1] = (i + 1) % N; // new seat
    }
    while (true) {
        time++;
        boolean changed = false;
        for (int i = 0; i < N; i++) {
            if (seat[i][0] != seat[i][1]) {
                changed = true;
                int temp = seat[i][0];
                seat[i][0] = seat[i][1];
                seat[i][1] = temp;
            }
        }
        if (!changed) {
            break;
        }
    }
    return time;
}

