public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = 1 << k; // 2^k
    if (n < m) {
        return false;
    }
    for (int i = 0; i < m; i++) {
        String code = Integer.toBinaryString(i);
        while (code.length() < k) {
            code = "0" + code;
        }
        if (!s.contains(code)) {
            return false;
        }
    }
    return true;
}

