                    up++;
                }

                // Traverse down
                for (int k = i + 1; k < m; k++) {
                    if (mat[k][j] == 0) break;
                    down++;
                }

                // Traverse left
                for (int k = j - 1; k >= 0; k--) {
                    if (mat[i][k] == 0) break;
                    left++;
                }

                // Traverse right
                for (int k = j + 1; k < n; k++) {
                    if (mat[i][k] == 0) break;
                    right++;
                }

                // Update the max length
                result = Math.max(result, up + down + left + right + 1);
            }
        }
    }

    return result;
}

