public boolean hasAllCodes(String s, int k) {
  if (s.length() < k) {
    return false;
  }

  char[] chars = s.toCharArray();
  for (int i = 0; i < s.length() - k + 1; i++) {
    StringBuilder sb = new StringBuilder();
    for (int j = 0; j < k; j++) {
      sb.append(chars[i + j]);
    }
    if (!sb.toString().equals(new String(chars, i, k))) {
      return false;
    }
  }
  return true;
}

