    int[] fib = new int[]{1, 1};
    int n = fib.length;
    while (n <= k) {
        fib[n] = fib[n - 1] + fib[n - 2];
        n++;
    }
    int num = k;
    int ans = 0;
    for (int n : fib) {
        while (n <= num) {
            num -= n;
            ans++;
        }
    }
    return ans;
}

