public static int squarePermutations(int[] A) {
    // First, find the sum of each pair of adjacent elements in the array
    int[] sums = new int[A.length - 1];
    for (int i = 0; i < A.length - 1; i++) {
        sums[i] = A[i] + A[i + 1];
    }

    // Then, check if each sum is a perfect square
    int count = 0;
    for (int sum : sums) {
        if (Math.sqrt(sum) == (int)Math.sqrt(sum)) {
            count++;
        }
    }

    // Finally, return the number of square permutations
    return (int)Math.pow(2, count);
}

