        int min = findMin(factors, index);
        sequence[i] = min * factors[min];

        for (int j = 0; j < factors.length; j++) {
            if (factors[j] == min) {
                factors[j] *= sequence[i];
            }
        }

        index++;
    }

    return sequence[n - 1];
}

