    int min = 0, left = 0, right = 0;
    for (char ch : s.toCharArray()) {
        if (ch == '(') left++;
        else right++;
        min = Math.min(min, left);
        min = Math.min(min, right);
    }
    return Math.min(min, left - min);
}

