    int num = que.poll();
    if (count++ == N) {
      return num;
    }
    int lastDigit = num % 4;
    if (lastDigit > 0) {
      que.offer(num + 1);
    }
    if (lastDigit < 3) {
      que.offer(num - 1);
    }
  }

  return -1;
}

