        fibonacciSum[i] = fibonacciSum[i - 1] + fibonacciSequence[i];
    }

    int minNumberOfElements = 0;
    for (int i = k; i >= 1; i--) {
        if (fibonacciSum[i] == k) {
            minNumberOfElements++;
        } else if (fibonacciSum[i] > k) {
            break;
        }
    }

    return minNumberOfElements;
}

