public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Collections.singletonList(nums[0]));
    } else {
        for (int i = 0; i < nums.length; i++) {
            int[] remaining = new int[nums.length - 1];
            System.arraycopy(nums, 0, remaining, 0, i);
            System.arraycopy(nums, i + 1, remaining, i, nums.length - i - 1);
            for (List<Integer> perm : permute(remaining)) {
                perm.add(0, nums[i]);
                result.add(perm);
            }
        }
    }
    return result;
}

