public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@') {
                // Check if the current cell is surrounded by four '@' neighbors
                if ((i > 0 && grid[i - 1][j] == '@') || (i < grid.length - 1 && grid[i + 1][j] == '@') ||
                        (j > 0 && grid[i][j - 1] == '@') || (j < grid[0].length - 1 && grid[i][j + 1] == '@')) {
                    count++;
                }
            }
        }
    }
    return count;
}

