public static double trimMean(int[] arr) {
    // Calculate the bounds of the top 90%.
    int index90Percentile = (int) (arr.length * 0.9);
    int index90PercentileMinus5Percent = (int) (arr.length * 0.9) - (arr.length * 0.05);
    int index90PercentilePlus5Percent = (int) (arr.length * 0.9) + (arr.length * 0.05);

    // Calculate the sum of the top 90%.
    int sum = 0;
    for (int i = index90PercentileMinus5Percent; i <= index90PercentilePlus5Percent; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the top 90%.
    return sum / (index90PercentilePlus5Percent - index90PercentileMinus5Percent + 1);
}

