public boolean splitArraySameAverage(int[] nums) {
  int sum = 0;
  for (int num : nums) {
    sum += num;
  }
  int avg = sum / nums.length;

  int leftSum = 0;
  int rightSum = sum;
  for (int i = 0; i < nums.length; i++) {
    if (leftSum + nums[i] <= avg) {
      leftSum += nums[i];
    } else if (rightSum - nums[i] <= avg) {
      rightSum -= nums[i];
    } else {
      return false;
    }
  }
  return true;
}

