    for (int i = 0; i < 10; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits);
    String result = "";
    for (int i = 0; i < 10; i++) {
        result += digits[i];
    }
    try {
        return Integer.parseInt(result) + 1;
    } catch (NumberFormatException e) {
        return -1;
    }
}

