public static String convertDatesToWeekdays(String date) {
    // split the input string into its constituent parts
    String[] dateParts = date.split(" ");

    // extract the month, day, and year from the date parts array
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    // create a Calendar object and set its date to the given date
    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);

    // get the weekday for the given date
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);

    // create a String array to hold the weekday names
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    // return the weekday name for the given date
    return weekdays[weekday - 1] + " " + day + ", " + year;
}

