public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a visited array to keep track of nodes we've visited
  boolean[] visited = new boolean[n];
  int[] times = new int[n]; // Initialize an array to keep track of times

  // BFS to find the shortest path to collect all apples
  Queue<Integer> queue = new LinkedList<>();
  queue.offer(0);
  visited[0] = true;
  times[0] = 0;
  while (!queue.isEmpty()) {
    int curr = queue.poll();
    for (int i = 0; i < edges[curr].length; i++) {
      int next = edges[curr][i];
      if (!visited[next]) {
        visited[next] = true;
        times[next] = times[curr] + 1;
        queue.offer(next);
      }
    }
  }

  // Find the shortest path to return to the starting node
  return times[0];
}

