public boolean splitArraySameAverage(int[] nums) {
  // Calculate the sum of the array elements
  int sum = 0;
  for (int num : nums) {
    sum += num;
  }

  // Calculate the average
  double average = (double) sum / nums.length;

  // Check if both arrays have the same average
  for (int i = 0; i < nums.length; i++) {
    int[] left = new int[i];
    int[] right = new int[nums.length - i - 1];
    for (int j = 0; j < i; j++) {
      left[j] = nums[j];
    }
    for (int j = i + 1; j < nums.length; j++) {
      right[j - i - 1] = nums[j];
    }
    if (left.length > 0 && right.length > 0 &&
        (left.stream().mapToDouble(x -> x).average().getAsDouble() == average ||
         right.stream().mapToDouble(x -> x).average().getAsDouble() == average)) {
      return true;
    }
  }

  return false;
}

