public int findMinFibonacciNumbers(int k) {
    // Initialize variables needed for the solution
    int[] fibonacciNumbers = new int[k];
    int n = 0;
    int sum = 0;

    // Initialize the first two Fibonacci numbers
    fibonacciNumbers[n++] = 1;
    fibonacciNumbers[n++] = 1;
    sum += fibonacciNumbers[n - 1];

    while (sum < k) {
        // Add the next Fibonacci number to the list
        fibonacciNumbers[n++] = fibonacciNumbers[n - 2] + fibonacciNumbers[n - 3];
        sum += fibonacciNumbers[n - 1];
    }

    // Return the minimum number of Fibonacci numbers needed to sum up to k
    return n;
}

