public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }
    int[] digits = new int[10];
    for (int i = 0; i < 10; i++) {
        digits[i] = i;
    }
    for (int i = 0; i < 10; i++) {
        int digit = n % 10;
        n /= 10;
        for (int j = 0; j < 9; j++) {
            if (digits[j] == digit) {
                break;
            }
            if (j == 8) {
                return i * 10 + digit;
            }
            digits[j] = digits[j + 1];
        }
        digits[9] = digit;
    }
    return -1;
}

