public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (true) {
        boolean isEqual = true;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] != arr[i + 1]) {
                isEqual = false;
                break;
            }
        }
        if (isEqual) {
            break;
        }

        int x = 0, y = 0;
        while (x < n && y < n) {
            if (arr[x] != arr[y]) {
                if (Math.abs(arr[x] - arr[y]) == 1) {
                    arr[x] -= 1;
                    arr[y] += 1;
                    minOperations++;
                    break;
                } else {
                    x++;
                    y++;
                }
            } else {
                x++;
                y++;
            }
        }
    }

    return minOperations;
}

