public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the index of the smallest 5% of elements
    int min = (int) Math.ceil(arr.length * 0.05);

    // Calculate the index of the largest 5% of elements
    int max = (int) Math.ceil(arr.length * 0.95);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = min; i < max; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = (double) sum / (arr.length - 2 * min);

    // Round the mean to 5 decimal places
    mean = Math.round(mean * 100000) / 100000;

    return mean;
}

