public static String appx(String word1, String word2) {
  int commonChars = 0;
  int totalChars = 0;

  for (int i = 0; i < word1.length(); i++) {
    for (int j = 0; j < word2.length(); j++) {
      if (word1.charAt(i) == word2.charAt(j)) {
        commonChars++;
      }
    }
  }

  totalChars = word1.length() + word2.length();

  if (totalChars == 0) {
    return "appx(empty string, empty string) = 1";
  }

  return "appx(" + word1 + ", " + word2 + ") = " + commonChars + "/" + totalChars;
