    dp[1] = 1;
    int p2 = 1, p3 = 1, p5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[p2] * 2, Math.min(dp[p3] * 3, dp[p5] * 5));
        dp[i] = min;
        if (min == dp[p2] * 2) {
            p2++;
        }
        if (min == dp[p3] * 3) {
            p3++;
        }
        if (min == dp[p5] * 5) {
            p5++;
        }
    }
    return dp[n];
}

