    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            stack.pop()
            current_group += char

        if char != "(" and char != ")":
            current_group += char

        if not stack:
            yield current_group
