    if not isbn.isdigit():
        raise ValueError("ISBN number must contain only digits")
    if not isbn[3] == "-" and not isbn[8] == "-" and not isbn[12] == "-":
        raise ValueError("ISBN number must be in the format 'X-XXX-XXXXX-X", isbn)

    # Calculate the checksum digit
    checksum = 0
    for i, digit in enumerate(isbn):
        if i % 2 == 0:
            checksum += int(digit)
        else:
            checksum += int(digit) * 3
    checksum = (10 - checksum % 10) % 10

    # Check if the checksum digit is correct
    if checksum == int(isbn[-1]):
        return "Right"
    else:
        return isbn[:-1] + str(checksum)

