public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] results = new int[rows * cols];
    int index = 0;

    // Initialize current diagonal index and direction
    int di = 0;
    int dj = 0;
    boolean goDown = true;

    while (index < rows * cols) {
        // Move in the current direction
        int i = di;
        int j = dj;

        while (i < rows && j < cols) {
            results[index++] = mat[i][j];
            i += di;
            j += dj;
        }

        // Change direction
        if (goDown) {
            if (i < rows && j == cols - 1) {
                di++;
            } else if (i == rows - 1) {
                dj++;
                goDown = false;
            }
        } else {
            if (j < cols && i == rows - 1) {
                dj++;
            } else if (j == cols - 1) {
                di--;
                goDown = true;
            }
        }
    }

    return results;
}

