    int insertCount = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            close++;
            if (close > open) {
                insertCount += close - open;
                open = close = 0;
            }
        }
    }

    return insertCount + open > close ? open - close : 0;
}

