public int findMinFibonacciNumbers(int k) {
        int[] fib = {1, 1, 2};
        Stack<Integer> stack = new Stack<>();
        while (k > 0) {
            for (int i = fib.length - 1; i >= 0 && fib[i] <= k; i--) {
                if (k == fib[i]) {
                    stack.push(fib[i]);
                    k = 0;
                    break;
                } else {
                    stack.push(fib[i]);
                    k -= fib[i];
                }
            }
        }
        int count = 0;
        while (!stack.isEmpty()) {
            stack.pop();
            count++;
        }
        return count;
    }

