public boolean canArrange(int[] arr, int k) {
        int[] freq = new int[k];

        for (int num : arr) {
            freq[(num % k) % k]++;
        }

        // Check if the pairs can be formed
        if ((num % 2 != 0 && k % 2 != 0) || freq[k / 2] % 2 == 1) {
            return false;
        }

        // Ensure that the frequency of each remainder class is even
        for (int i = 1; i < k; i++) {
            if (freq[i] % 2 != 0) {
                return false;
            }
        }

        return true;
    }

