public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n];
    dp[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next factor = 2, 3, 5;

    for (int i = 1; i < n; i++) {
        next factor = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = next factor;

        if (next factor == dp[i2] * 2) {
            i2++;
        }
        if (next factor == dp[i3] * 3) {
            i3++;
        }
        if (next factor == dp[i5] * 5) {
            i5++;
        }
    }

    return dp[n - 1];
}

