public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int targetSum = totalSum / 2;

    int[] prefixSum = new int[n];
    prefixSum[0] = nums[0];
    for (int i = 1; i < n; i++) {
        prefixSum[i] = prefixSum[i - 1] + nums[i];
    }

    for (int i = 0; i < n - 1; i++) {
        int remainingSum = prefixSum[n - 1] - prefixSum[i];
        if (remainingSum % i == 0 && remainingSum / i == targetSum) {
            return true;
        }
    }

    return false;
}

