public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Initialize left indices
    for (int i = 0; i < n; i++) {
        left[i] = i;
        while (i > 0 && heights[left[i-1]] >= heights[i]) {
            left[i-1] = left[i];
        }
    }

    // Initialize right indices
    for (int i = n - 1; i >= 0; i--) {
        right[i] = i;
        while (i < n - 1 && heights[right[i+1]] >= heights[i]) {
            right[i+1] = right[i];
        }
    }

    // Calculate area of each rectangle
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        maxArea = Math.max(maxArea, width * heights[i]);
    }

    return maxArea;
}

