public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int min = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int value = i * i;
        int rem = n - value;
        min = Math.min(min, 1 + minPerfectSquareSum(rem));
    }
    return min;
}

