public int findMinFibonacciNumbers(int k) {
        int[] fib = {1, 1, 2, 3, 5, 8, 13, 21};
        int[] result = new int[8];
        int index = 7;

        while (k > 0) {
            if (k >= fib[index]) {
                result[index] = 1;
                k -= fib[index];
            } else {
                index--;
            }
        }

        return Arrays.stream(result).filter(x -> x == 1).sum();
    }

