public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0) {
            return new int[0];
        }

        int numR = mat.length;
        int numC = mat[0].length;
        int count = numR * numC;

        int[][] dirs = new int[][]{{1, 0}, {0, 1}};
        boolean[][] visited = new boolean[numR][numC];

        int[] result = new int[count];
        int row = 0;
        int col = 0;
        for (int i = 0; i < count; i++) {
            result[i] = mat[row][col];
            visited[row][col] = true;

            int newRow = row + dirs[0][0];
            int newCol = col + dirs[0][1];

            if (!visited[newRow][newCol]) {
                row = newRow;
                col = newCol;
            } else {
                int potentiallyRow = row;
                int potentiallyCol = col;
                row += dirs[1][0];
                col += dirs[1][1];

                if (row < 0 || row >= numR || col < 0 || col >= numC) {
                    continue;
                }

                newRow = row;
                newCol = col;
                rows = potentiallyRow;
                cols = potentiallyCol;
                dirs = dirs[0] == dirs[1] ? new int[][]{{-1, 1}, {1, -1}} : new int[][]{{1, 1}, {1, -1}};
            }
        }

        return result;
    }

