public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;

    for (int length = 1; length <= n; length++) {
        if (length % 2 == 1) {
            result.add("1");
        } else {
            for (int i = 1; i <= length / 2; i++) {
                result.add(String.format("%d%d", i, i));
            }
        }
    }

    return result;
}

