public static int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        if (n == 0) return 0;
        if (n == 1) return cost[0];

        int prev1 = cost[0];
        int prev2 = cost[1];
        for (int i = 2; i < n; i++) {
            int current = Math.min(prev1 + cost[i], prev2 + cost[i]);
            prev1 = prev2;
            prev2 = current;
        }
        return prev2;
    }

