public boolean canArrange(int[] arr, int k) {
    // Count numbers with each possible remainder when divided by k
    int[] count = new int[k];
    for (int num : arr) {
        if (num != 0) {
            count[num % k]++;
        } else {
            count[k]++;
        }
    }

    int n = arr.length;
    for (int i = 1; i <= n / 2; i++) {
        int complement = k - i;
        if (i % 2 == 0) {
            if (complement < 0 || (complement > 0 && count[complement] < 2)) {
                return false;
            }
        } else {
            if (complement < 0 || count[complement] != 2) {
                return false;
            }
        }
    }
    return true;
}

