public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }

    // A number is a power of two if it has only one bit set in its binary representation.
    // We can check this using bitwise AND operation with n - 1.
    return (n & (n - 1)) == 0;
}

