public static int squarePermutations(int[] A) {
    if (A.length == 0) {
        return 0;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        for (int j = i + 1; j < A.length; j++) {
            if (A[j] - A[i] >= 0 && Math.sqrt(A[j] - A[i]) * Math.sqrt(A[j] - A[i]) == A[j] - A[i]) {
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
                count += 1;
            }
        }
    }

    return count;
}

