public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;

    int rows = 2 * m - 1;
    int cols = 2 * n - 1;

    int[] res = new int[rows * cols];

    // Keep track of the positions for first row & col
    int rr, cc;
    // keep track of the diagonal number
    int curDiag = 0;

    for(int i = 0; i < res.length; i++) {
        if(curDiag % 2 == 0) {
            rr = curDiag + 1 - (curDiag / 2);
            cc = curDiag / 2;
        } else {
            rr = curDiag / 2;
            cc = curDiag + 1 - (curDiag / 2);
        }

        // Edge checks
        if(rr < 0) rr = 0;
        if(rr >= m) rr = m - 1;
        if(cc < 0) cc = 0;
        if(cc >= n) cc = n - 1;

        res[i] = mat[rr][cc];
        if(curDiag % 2 == 0) curDiag++;
        else curDiag--;
    }
    return res;
}

