public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    Map<Integer, Integer> freq = new HashMap<>();
    for (int num : arr) {
        freq.put(num % k, freq.getOrDefault(num % k, 0) + 1);
    }

    for (int i = 1; i <= k / 2; i++) {
        if (freq.getOrDefault(i, 0) != freq.getOrDefault(k - i, 0)) {
            return false;
        }
    }

    return true;
}

