public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    // If n is a power of two, it should have exactly one bit set in its binary representation.
    // We use the logarithm base 2 to find the number of bits in n's binary representation.
    // If the number of bits is 1, then n is a power of two.
    if ((Math.log(n) / Math.log(2)) % 1 == 0) {
        return true;
    } else {
        return false;
    }
}

