public boolean splitArraySameAverage(int[] nums) {
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    if (total % 2 != 0) {
        return false;
    }
    int target = total / 2;
    int[] sumPrefix = new int[nums.length];
    sumPrefix[0] = nums[0];
    for (int i = 1; i < nums.length; i++) {
        sumPrefix[i] = sumPrefix[i - 1] + nums[i];
    }
    int sumSuffix = 0;
    for (int i = sumPrefix.length - 1; i >= 0; i--) {
        sumSuffix += nums[i];
    }
    for (int i = 0; i < sumPrefix.length - 1; i++) {
        int difference = sumPrefix[i] - target;
        if (sumSuffix - difference == target) {
            return true;
        }
    }
    return false;
}

