public static String addThousandSeparator(int n) {
    if (n < 0) return "-" + addThousandSeparator(-n); // Ensure the function works for negative numbers

    int sign = n < 0 ? -1 : 1;
    n = Math.abs(n);
    str = String.valueOf(n);
    int strLen = str.length();
    sb = new StringBuilder(strLen + 3);

    if (strLen <= 3) return str; // No separator needed, return the number as is

    for (int i = strLen - 3; i > 0; i--) {
        sb.insert(i, '.'); // Insert a dot after every three digits except at the beginning
    }

    String result = sign > 0 ? sb.toString() : "-" + sb.toString();
    return result; // Return the string with thousand separators added
}

