public static int minPerfectSquareSum(int n) {
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0; // Base case: 0 perfect squares need 0 squared numbers

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                int square = j * j;
                if (square <= i) {
                    dp[i] = Math.min(dp[i], dp[i - square] + 1);
                }
            }
        }
        return dp[n];
    }

