def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Use dynamic programming to solve the subset sum problem
    dp = [False] * (V + 1)
    dp[0] = True

    for volume in volumes:
        for weight in range(V, volume - 1, -1):
            if dp[weight]:
                dp[weight + volume] = True

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - max(0, V - sum(volumes[i] for i in range(n) if dp[volumes[i]]))

