def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: if n is less than x, it's impossible to partition it into k parts
    if n < x * k:
        return 0

    # Initialize the DP table
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: one way to partition 0 into 0 parts
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i >= x * j:
                dp[i][j] = dp[i - x * j][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][k]

