def max_energy(beads):
    n = len(beads)

    # Initialize a 2D array to store the maximum energy for sub-sequences
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if beads[i] == beads[j]:
                dp[i][j] = dp[i+1][j-1] + beads[i] ** 2
