public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (k >= num) {
                    dp[j][i][k] = dp[j][i - 1][k] || dp[j - 1][i - 1][k - num];
                } else {
                    dp[j][i][k] = dp[j][i - 1][k];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= i; j++) {
            if (sum * j % n == 0 && dp[j][n][sum * j / n]) {
                return true;
            }
        }
    }

    return false;
}

