                    if (k + num <= sum) {
                        dp[j][i][k + num] = true;
                    }
                }
            }
        }
    }

    for (int lenA = 1; lenA <= n / 2; lenA++) {
        if (sum * lenA % n == 0) {
            int sumA = sum * lenA / n;
            if (dp[lenA][n][sumA]) {
                return true;
            }
        }
    }

    return false;
}

