public int findMinFibonacciNumbers(int k) {
    if (k < 1) return 0;

    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    while (k > 0) {
        while (a > k) {
            int temp = a - b;
            b = a;
            a = temp;
        }
        k -= a;
        count++;
    }
    return count;
}

