public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty() || k <= 0 || k > s.length()) {
        return false;
    }

    int total = 1 << k; // 2^k
    boolean[] seen = new boolean[total];
    int allOnes = total - 1;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & allOnes | (s.charAt(i) - '0');
        if (i - k + 1 >= 0 && !seen[value]) {
            seen[value] = true;
            total--;
            if (total == 0) {
                return true;
            }
        }
    }

    return false;
}

