public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate all Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int temp = a + b;
        a = b;
        b = temp;
    }

    // b is now the first Fibonacci number greater than k, so we use a
    return 1 + findMinFibonacciNumbers(k - a);
}

