    int n = mat[0].length;
    int maxLength = 0;

    // Directions: horizontal, vertical, diagonal, and anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
