public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int allOnes = (1 << k) - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); ++i) {
        hashVal = ((hashVal & allOnes) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(hashVal);
        }
    }

    return seen.size() == (1 << k);
}

