public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    int[][][] dp = new int[rows][cols][4];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (i > 0) ? dp[i - 1][j][0] + 1 : 1; // vertical
                dp[i][j][1] = (j > 0) ? dp[i][j - 1][1] + 1 : 1; // horizontal
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1; // diagonal
                dp[i][j][3] = (i > 0 && j < cols - 1) ? dp[i - 1][j + 1][3] + 1 : 1; // anti-diagonal

                for (int k = 0; k < 4; k++) {
                    maxLength = Math.max(maxLength, dp[i][j][k]);
                }
            }
        }
    }

    return maxLength;
}

