public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int val = 0;
    int mask = (1 << k) - 1;

    for (int i = 0; i < s.length(); i++) {
        val = (val << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && seen.add(val) && seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

