public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][sum + 1][n + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = n / 2; j >= 0; j--) {
            for (int k = sum; k >= num; k--) {
                for (int l = i - 1; l >= 0; l--) {
                    if (dp[j][k][l]) {
                        dp[j + 1][k + num][i] = true;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            int targetSum = sum * i / n;
            if (dp[i][targetSum][n]) {
                return true;
            }
        }
    }

    return false;
}

