public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int n = s.length();

    while (result.length() < n) {
        for (char c = 'a'; c <= 'z'; c++) {
            if (count[c - 'a'] > 0) {
                result.append(c);
                count[c - 'a']--;
            }
        }
        for (char c = 'z'; c >= 'a'; c--) {
            if (count[c - 'a'] > 0) {
                result.append(c);
                count[c - 'a']--;
            }
        }
    }

    return result.toString();
}

