public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] dp = new boolean[n / 2 + 1][sum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int j = 0; j <= sum - num; j++) {
                if (dp[i - 1][j]) {
                    dp[i][j + num] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

