public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int totalPossibleCodes = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleCodes];

    for (int i = 0; i <= s.length() - k; i++) {
        int index = 0;
        for (int j = 0; j < k; j++) {
            index = (index << 1) + (s.charAt(i + j) - '0');
        }
        found[index] = true;
    }

    for (boolean codeFound : found) {
        if (!codeFound) {
            return false;
        }
    }

    return true;
}

