public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int i = 0; i < strings.size(); i++) {
        for (int j = 0; j <= strings.get(i).length(); j++) {
            for (int k = j + 1; k <= strings.get(i).length(); k++) {
                String substring = strings.get(i).substring(j, k);
                String inverse = new StringBuilder(substring).reverse().toString();
                boolean allContain = true;

                for (String str : strings) {
                    if (!str.contains(substring) && !str.contains(inverse)) {
                        allContain = false;
                        break;
                    }
                }

                if (allContain) {
                    maxLength = Math.max(maxLength, substring.length());
                }
            }
        }
    }

    return maxLength;
}

