def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * (N + 1) for _ in range(N + 1)]

    # Fill the grid with given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # DP table to store the maximum value collected by two paths
    dp = [[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]

    # Base case: starting point
    dp[1][1][1] = grid[1][1]

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                l = (i + j) - k
                if l < 1 or l > N:
                    continue
                if dp[i-1][j][k] == -1 and dp[i][j-1][k] == -1 and dp[i-1][j][k-1] == -1 and dp[i][j-1][k-1] == -1:
                    continue
                if i == 1 and j == 1 and k == 1 and l == 1:
                    continue
                val1 = grid[i][j]
                val2 = grid[k][l]
                if i == k and j == l:
                    value = val1
                else:
                    value = val1 + val2

                dp[i][j][k] = value + max([
                    dp[i-1][j][k-1] if i > 1 and k > 1 else -1,
                    dp[i-1][j][k] if i > 1 else -1,
                    dp[i][j-1][k-1] if j > 1 and k > 1 else -1,
                    dp[i][j-1][k] if j > 1 else -1
                ])

    return dp[N][N][N] if dp[N][N][N] != -1 else 0

