    # Check if lengths of encoded and original are the same
    if len(encoded) != len(original):
        return "Failed"

    # Build the mapping from encoded to original
    mapping = {}
    for enc, org in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != org:
                return "Failed"  # Contradiction in mapping
        else:
            mapping[enc] = org

    # Check if all letters in the message are in the mapping
    decoded_message = []
    for char in message:
