    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        absolute_coeff = abs(coeff)
        sign = '+' if coeff > 0 else '-'

        if degree == 0:
            term = str(absolute_coeff)
        elif degree == 1:
            term = 'x' if absolute_coeff == 1 else f'{absolute_coeff}x'
        else:
            term = f'x^{degree}' if absolute_coeff == 1 else f'{absolute_coeff}x^{degree}'

        # For the first term, we should not prepend with a '+'
        if not terms:
            terms.append(term if coeff > 0 else '-' + term)
        else:
            terms.append(sign + term)

    return ''.join(terms)

