def count_partitions(n: int, k: int, x: int) -> int:
    # Validate inputs
    if n < k * x or k <= 0 or x <= 0:
        return 0

    # Use dynamic programming to solve the partition problem
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        dp[i][0] = 1

    for i in range(1, k + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j]
            if j - x >= 0:
                dp[i][j] += dp[i][j - x]

    return dp[k][n]

