    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")
    if y0 % x0 != 0:
        return 0

    from math import gcd

    count = 0
    quotient = y0 // x0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

