def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0:
        raise ValueError("Budget and number of items must be non-negative.")
    if any(price < 0 or importance < 0 for price, importance in items):
        raise ValueError("Price and importance of items must be non-negative.")

    # Initialize a list to store the maximum importance value for each budget up to n
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the dp array from back to front to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
