public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum sum of 1^2 + 1^2 + ...
    }

    for (int i = 2; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - i * i] + 1);
        }
    }

    return dp[n];
}

