public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) sum += num;
    boolean[][] dp = new boolean[n + 1][sum + 1];

    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = sum; j >= 0; j--) {
            for (int k = 0; k <= j / num; k++) {
                dp[i][j] = dp[i][j] || dp[i - 1][j - k * num];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= sum; j++) {
            if (dp[i][j] && dp[n - i][sum - j]) {
                return true;
            }
        }
    }

    return false;
}

