public static int squarePermutations(int[] A) {
    if (A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];
    dp[0][1 << 0] = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < 1 << n; j++) {
            for (int k = 0; k < n; k++) {
                if ((j & (1 << k)) != 0) {
                    int sum = A[k] + A[i];
                    if (isPerfectSquare(sum)) {
                        dp[i][j | (1 << i)] += dp[k][j];
                    }
                }
            }
        }
    }

    int result = 0;
    for (int i = 0; i < 1 << n; i++) {
        result += dp[n - 1][i];
    }

    return result;
}

