public int findMinFibonacciNumbers(int k) {
    List<Integer> fibonacci = new ArrayList<>();
    int a = 1, b = 1;
    fibonacci.add(a);
    while (b <= k) {
        fibonacci.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    while (k > 0) {
        int index = Collections.binarySearch(fibonacci, k);
        if (index < 0) {
            index = -index - 1;
        }
        k -= fibonacci.get(index);
        count++;
    }

    return count;
}

