    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }

    int count = 0;
    int year = Y;

    while (count < N) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }

    return -1; // In case N leap years are not found after the start year
}

