public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int[] dp = new int[n + 1];

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum number of 1s
    }

    for (int i = 4; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

