public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = n; j >= 1; j--) {
            for (int k = n; k >= num; k--) {
                dp[j][k] = dp[j][k] || dp[j - 1][k - num];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (i * sum % n == 0 && dp[i][i * sum / n]) {
            return true;
        }
    }

    return false;
}

