public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            close++;
            if (close > open) {
                insertions++;
                open++;
            }
        }
    }

    if (open > close) {
        insertions += 2 * (open - close);
    } else if (close - open == 1) {
        insertions++;
    }

    return insertions;
}

