public int findMinFibonacciNumbers(int k) {
    if (k <= 2) {
        return k;
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);

    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    int count = 0;
    while (k > 0) {
        int largestFib = fibs.get(fibs.size() - 1);
        if (k >= largestFib) {
            k -= largestFib;
            count++;
        } else {
            fibs.remove(fibs.size() - 1);
        }
    }

    return count;
}

