public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int res = n;
    for (int i = 1; i <= n; i++) {
        int square = i * i;
        if (square > n) {
            break;
        } else {
            res = Math.min(res, 1 + minPerfectSquareSum(n - square));
        }
    }
    return res;
}

