                for (String str : strings) {
                    if (!str.contains(s) && !str.contains(new StringBuilder(s).reverse().toString())) {
                        isFound = false;
                        break;
                    }
                }
                if (isFound) {
                    maxLength = currentLength;
                }
            }
        }

        return maxLength;
    }

