    int count = 0;
    for (int i = 0; i < numbers.length; i++) {
        for (int j = 0; j < numbers.length; j++) {
            if (numbers[i] == 2 * numbers[j] && i != j) {
                count++;
                break;
            }
        }
    }
    return count;
}

