    Arrays.sort(arr);
    int n = arr.length;
    int trimSize = (int) (0.05 * n);
    int sum = 0;
    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }
    return (double) sum / (n - 2 * trimSize);
}

