public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] possible = new boolean[n + 1][sum + 1];
    possible[0][0] = true;

    for (int num : nums) {
        for (int i = n; i >= 1; i--) {
            for (int j = sum; j >= 0; j--) {
                if (j >= num) {
                    possible[i][j] = possible[i][j] || possible[i - 1][j - num];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (possible[i][i * sum / n] && i * sum % n == 0) {
            return true;
        }
    }

    return false;
}

