public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Consume the next character
            } else {
                insertions++; // Need an extra ')' to balance
            }
            close++;
        }
    }

    // Balance the unmatched parentheses
    insertions += (open - close) * 2;

    return insertions;
}

