public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    // Generate Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    List<Integer> fibNumbers = new ArrayList<>();
    fibNumbers.add(a);
    fibNumbers.add(b);
    while (b <= k) {
        int sum = a + b;
        a = b;
        b = sum;
        fibNumbers.add(b);
    }

    // Use greedy algorithm to find the minimum number of Fibonacci numbers
    int count = 0;
    int i = fibNumbers.size() - 1;
    while (k > 0 && i >= 0) {
        if (k >= fibNumbers.get(i)) {
            k -= fibNumbers.get(i);
            count++;
        } else {
            i--;
        }
    }

    return count;
}

