public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            Set<Integer> seen = new HashSet<>();
            for (int j = 0; j < 1 << i; j++) {
                int subSum = 0;
                for (int k = 0; k < i; k++) {
                    if ((j & (1 << k)) != 0) {
                        subSum += nums[k];
                    }
                }
                seen.add(subSum);
            }
            for (int j = 0; j < 1 << (n - i); j++) {
                int subSum = 0;
                for (int k = 0; k < n - i; k++) {
                    if ((j & (1 << k)) != 0) {
                        subSum += nums[i + k];
                    }
                }
                if (seen.contains(sum - subSum)) {
                    return true;
                }
            }
        }
    }
    return false;
}

