public String makeGood(String s) {  
    Stack<Character> stack = new Stack<>();  
    for (char c : s.toCharArray()) {  
        if (stack.isEmpty()) {  
            stack.push(c);  
            continue;  
        }  
        if (Character.isUpperCase(c) && stack.peek() == Character.toLowerCase(c)) {  
            stack.pop();  
        } else if (Character.isLowerCase(c) && stack.peek() == Character.toUpperCase(c)) {  
            stack.pop();  
        } else {  
            stack.push(c);  
        }  
    }  
    StringBuilder result = new StringBuilder();  
    for (char c : stack) {  
        result.append(c);  
    }  
    return result.toString();  
}

