public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                insertions++;
            }
            balance--;
        }

        if (balance < 0) {
            insertions++;
            balance = 0;
        }
    }

    return insertions + 2 * balance;
}

