    if (closingBalances == null || closingBalances.size() != 12) {
        throw new IllegalArgumentException("Input list must contain exactly 12 closing balances.");
    }

    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            throw new IllegalArgumentException("All balances in the list must be non-null.");
        }
        sum += balance;
    }

    return sum / 12;
