def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    level = 0
    current = 0

    while current < N:
        level += 1
        current += level

    if level % 2 == 0:
        numerator = N - (current - level) + 1
        denominator = level - (N - (current - level) - 1)
    else:
        numerator = level - (N - (current - level) - 1)
        denominator = N - (current - level) + 1

    return f"{numerator}/{denominator}"

