public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (sb.length() < s.length()) {
        /* Ascending part */
        int lastAsc = -1;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                lastAsc = i;
                break;
            }
        }
        if (lastAsc != -1) {
            for (int i = lastAsc + 1; i < 26; i++) {
                if (freq[i] > 0) {
                    sb.append((char) ('a' + i));
                    freq[i]--;
                    lastAsc = i;
                }
            }
        }
        /* Descending part */
        int lastDesc = -1;
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                lastDesc = i;
                break;
            }
        }
        if (lastDesc != -1) {
            for (int i = lastDesc - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    sb.append((char) ('a' + i));
                    freq[i]--;
                }
            }
        }
    }
    return sb.toString();
}

