public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long abs = Math.abs((long) n);
    String s = Long.toString(abs);
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    int first = len % 3;
    if (first == 0) first = 3;
    sb.append(s, 0, first);
    for (int i = first; i < len; i += 3) {
        sb.append('.').append(s, i, i + 3);
    }
    if (negative) sb.insert(0, '-');
    return sb.toString();
}

