public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0 && high >= 0) {
        result.add(0);
    }
    Queue<Long> queue = new ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        long nextNum;
        if (lastDigit > 0) {
            nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

