    int row = 0, col = 0;
    boolean up = true;

    while (index < m * n) {
        res[index++] = mat[row][col];
        if (up) {
            if (col == n - 1) { // hit right edge
                row++;
                up = false;
            } else if (row == 0) { // hit top edge
                col++;
                up = false;
            } else { // move up-right
                row--;
                col++;
            }
        } else { // down-left
            if (row == m - 1) { // hit bottom edge
                col++;
                up = true;
            } else if (col == 0) { // hit left edge
                row++;
                up = true;
            } else { // move down-left
                row++;
                col--;
            }
        }
    }
    return res;
}

