public static int findSmallestInteger(int n) {
    char[] c = String.valueOf(n).toCharArray();
    int[] d = new int[c.length];
    for (int i = 0; i < c.length; i++) {
        d[i] = c[i] - '0';
    }

    // Find the first index from the end where d[i] < d[i+1]
    int i = d.length - 2;
    while (i >= 0 && d[i] >= d[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit greater than d[i] in the suffix
    int j = d.length - 1;
    while (d[j] <= d[i]) {
        j--;
    }

    // Swap
    int tmp = d[i];
    d[i] = d[j];
    d[j] = tmp;

    // Reverse the suffix
    int l = i + 1;
    int r = d.length - 1;
    while (l < r) {
        tmp = d[l];
        d[l] = d[r];
        d[r] = tmp;
        l++;
        r--;
    }

    // Convert back to integer, check for overflow
    long result = 0;
    for (int val : d) {
        result = result * 10 + val;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) result;
}

