public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int best = Integer.MAX_VALUE;
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            int cand = dp[i - square] + 1;
            if (cand < best) {
                best = cand;
            }
        }
        dp[i] = best;
    }
    return dp[n];
}

