public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    int[] cur = java.util.Arrays.copyOf(nums, n);
    java.util.Arrays.sort(cur);
    while (true) {
        java.util.List<Integer> list = new java.util.ArrayList<>(n);
        for (int v : cur) {
            list.add(v);
        }
        res.add(list);
        int i = n - 2;
        while (i >= 0 && cur[i] >= cur[i + 1]) {
            i--;
        }
        if (i < 0) {
            break;
        }
        int j = n - 1;
        while (cur[j] <= cur[i]) {
            j--;
        }
        int temp = cur[i];
        cur[i] = cur[j];
        cur[j] = temp;
        int left = i + 1;
        int right = n - 1;
        while (left < right) {
            int t = cur[left];
            cur[left] = cur[right];
            cur[right] = t;
            left++;
            right--;
        }
    }
    return res;
}

