public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    // dp[k] will contain all possible sums of subsets of size k
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = n; k >= 1; k--) {
            java.util.Set<Integer> prev = dp.get(k - 1);
            if (!prev.isEmpty()) {
                java.util.Set<Integer> curr = dp.get(k);
                for (int sum : prev) {
                    curr.add(sum + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if (total % k == 0) {
            int target = total / k;
            if (dp.get(k).contains(target)) {
                return true;
            }
        }
    }
    return false;
}

