public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    long pos = 1;
    while (n / pos > 0) {
        int high = (int) (n / (pos * 10));
        int cur = (int) ((n / pos) % 10);
        int low = (int) (n % pos);

        if (cur == 0) {
            count += high * (int) pos;
        } else if (cur == 1) {
            count += high * (int) pos + low + 1;
        } else {
            count += (high + 1) * (int) pos;
        }
        pos *= 10;
    }
    return count;
}

