public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;

    for (int sum = 0; sum < m + n - 1; sum++) {
        if ((sum & 1) == 0) { // even sum -> traverse bottom-up
            int row = Math.min(sum, m - 1);
            int col = sum - row;
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd sum -> traverse top-down
            int col = Math.min(sum, n - 1);
            int row = sum - col;
            while (col >= 0 && row < m) {
                result[index++] = mat[row][col];
                col--;
                row++;
            }
        }
    }
    return result;
}

