public static int countDoubles(int[] numbers) {
    int count = 0;
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    for (int num : numbers) {
        if ((num & 1) == 0 && set.contains(num >> 1)) {
            count++;
        }
    }
    return count;
}

