public static String convertDatesToWeekdays(String date) {
    try {
        java.text.SimpleDateFormat inputFormat = new java.text.SimpleDateFormat("MM dd yyyy", java.util.Locale.ENGLISH);
        inputFormat.setLenient(false);
        java.util.Date parsedDate = inputFormat.parse(date);

        java.text.SimpleDateFormat monthDayFormat = new java.text.SimpleDateFormat("MMMM d, yyyy", java.util.Locale.ENGLISH);
        java.text.SimpleDateFormat weekdayFormat = new java.text.SimpleDateFormat("EEEE", java.util.Locale.ENGLISH);

        String monthDay = monthDayFormat.format(parsedDate);
        String weekday = weekdayFormat.format(parsedDate);

        return monthDay + " is a " + weekday;
    } catch (java.text.ParseException e) {
        return "Invalid date";
    }
}

