public double trimMean(int[] arr) {
    int n = arr.length;
    int trim = n / 20; // number of elements to remove from each side
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    return sum / (double) (n - 2 * trim);
}

