    String s = Integer.toString(absN);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = s.length() - 1; i >= 0; i--) {
        sb.append(s.charAt(i));
        count++;
        if (count % 3 == 0 && i != 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

