public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    class Helper {
        boolean dfs(int node, int parent) {
            boolean containsApple = hasApple[node];
            for (int nei : graph[node]) {
                if (nei == parent) continue;
                if (dfs(nei, node)) {
                    res[0] += 2;
                    containsApple = true;
                }
            }
            return containsApple;
        }
    }
    new Helper().dfs(0, -1);
    return res[0];
}

