public String sortString(String s) {
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass
        for (Character c : new ArrayList<>(freq.keySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
        if (freq.isEmpty()) break;
        // Descending pass
        for (Character c : new ArrayList<>(freq.descendingKeySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
    }
    return result.toString();
}

