public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k.
    int[] fib = new int[50]; // enough for k up to 10^9
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }

    // Greedy selection of the largest Fibonacci number <= remaining k.
    int count = 0;
    while (k > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= k) {
                k -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

