public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int rStart = Math.max(0, d - n + 1);
        int rEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rEnd; r >= rStart; r--) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        } else {
            for (int r = rStart; r <= rEnd; r++) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        }
    }
    return res;
}

