public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    class Backtrack {
        void dfs(int start, int[] arr) {
            if (start == arr.length) {
                List<Integer> tmp = new ArrayList<>();
                for (int v : arr) {
                    tmp.add(v);
                }
                res.add(tmp);
                return;
            }
            for (int i = start; i < arr.length; i++) {
                int temp = arr[start];
                arr[start] = arr[i];
                arr[i] = temp;
                dfs(start + 1, arr);
                temp = arr[start];
                arr[start] = arr[i];
                arr[i] = temp;
            }
        }
    }
    new Backtrack().dfs(0, nums.clone());
    return res;
}

