public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int remove = n / 20;  // 5% of n, rounded down
    int newLen = n - 2 * remove;
    if (newLen <= 0) {
        return 0.0;
    }
    int[] copy = arr.clone();
    java.util.Arrays.sort(copy);
    double sum = 0.0;
    for (int i = remove; i < n - remove; i++) {
        sum += copy[i];
    }
    return sum / newLen;
}

