public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    char[] arr = s.toCharArray();
    java.util.Arrays.sort(arr);
    StringBuilder sb = new StringBuilder(arr.length);
    int start = 0;
    int end = arr.length - 1;
    while (start <= end) {
        // Ascending pass
        while (start <= end) {
            sb.append(arr[start]);
            start++;
        }
        // Descending pass
        while (start <= end) {
            sb.append(arr[end]);
            end--;
        }
    }
    return sb.toString();
}

