public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String base = strings.get(0);
    int maxLen = 0;
    int L = base.length();
    for (int i = 0; i < L; i++) {
        for (int j = i + 1; j <= L; j++) {
            String sub = base.substring(i, j);
            int len = sub.length();
            if (len <= maxLen) {
                continue;
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (s.indexOf(sub) < 0 && s.indexOf(rev) < 0) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                maxLen = len;
            }
        }
    }
    return maxLen;
}

