public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int nd : nextDigits) {
            if (nd >= 0 && nd <= 9) {
                long nextNum = num * 10 + nd;
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

