public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(Math.max(0, n));
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr += 1;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr += 1;
        }
    }
    return result;
}

