public static int countDoubles(int[] numbers) {
    // If the input array is empty or has one element, there can be no doubles
    if (numbers == null || numbers.length < 2) {
        return 0;
    }

    // Use a HashSet for O(1) lookup of possible half-values
    java.util.Set<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }

    int count = 0;
    for (int num : numbers) {
        // A number can only be twice another if it is even (or zero)
        if (num % 2 == 0) {
            int half = num / 2;
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

