public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    if (total > Integer.MAX_VALUE / 2) return false; // overflow guard
    boolean[] seen = new boolean[total];
    int cur = 0;
    for (int i = 0; i < k; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    seen[cur] = true;
    int count = 1;
    int mask = total - 1;
    for (int i = k; i < n; i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[cur]) {
            seen[cur] = true;
            count++;
        }
    }
    return count == total;
}

