public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int current = (i == n) ? 0 : heights[i];
        while (top != -1 && current < heights[stack[top]]) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

