public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = (int) Math.floor(n * 0.05);
    int start = trim;
    int end = n - 1 - trim;
    if (start > end) {
        return 0.0;
    }
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    int count = end - start + 1;
    return sum / (double) count;
}

