public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }
    int year = Y;
    int count = 0;
    while (true) {
        if ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
        // Avoid integer overflow
        if (year == Integer.MAX_VALUE) {
            throw new IllegalStateException("Exceeded integer range while searching for the Nth leap year.");
        }
    }
}

