public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // ensure non‑negative
        freq[r]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        int half = k / 2;
        if (freq[half] % 2 != 0) {
            return false;
        }
    }
    // check other remainders
    for (int r = 1; r < k / 2 + 1; r++) {
        int complement = (k - r) % k;
        if (r == complement) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

