public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // opposite case letters
                sb.setLength(len - 1); // remove the pair
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

