public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

