public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long pos = 1;
    while (pos <= n) {
        long high = n / (pos * 10);
        long cur = (n / pos) % 10;
        long low = n % pos;
        if (cur == 0) {
            count += high * pos;
        } else if (cur == 1) {
            count += high * pos + low + 1;
        } else {
            count += (high + 1) * pos;
        }
        if (pos > Long.MAX_VALUE / 10) {
            break; // prevent overflow on next multiplication
        }
        pos *= 10;
    }
    return (int) count;
}

