public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // worst case: all 1^2
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

