    dp = [False] * (V + 1)
    dp[0] = True
    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    max_used = 0
