def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for ai in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0] % MOD
