def cantor_numbering(N: int) -> str:
    # Find diagonal d such that d(d+1)/2 >= N
    lo, hi = 1, 1
    while hi * (hi + 1) // 2 < N:
        hi <<= 1  # double hi
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    d = lo
    prev_total = (d - 1) * d // 2
    idx = N - prev_total  # 1-based index inside the diagonal
    if d % 2 == 0:
        numer = idx
        denom = d - idx + 1
    else:
        numer = d - idx + 1
        denom = idx
    return f"{numer}/{denom}"

